// Door geometry and collision share the same hinge, angle and rectangle.
export function doorPose(p,open){const vertical=p.d>p.w,angle=open?(vertical?Math.PI*.51:-Math.PI*.51):0,hx=p.x-(vertical?0:p.w/2),hz=p.z-(vertical?p.d/2:0),lx=vertical?0:p.w/2,lz=vertical?p.d/2:0,c=Math.cos(angle),s=Math.sin(angle);return{x:hx+c*lx+s*lz,z:hz-s*lx+c*lz,w:p.w,d:p.d,angle};}
export function circleHitsBox(x,z,r,b){const c=Math.cos(b.angle||0),s=Math.sin(b.angle||0),dx=x-b.x,dz=z-b.z,lx=c*dx-s*dz,lz=s*dx+c*dz,qx=Math.max(-b.w/2,Math.min(b.w/2,lx)),qz=Math.max(-b.d/2,Math.min(b.d/2,lz));return (lx-qx)**2+(lz-qz)**2<r*r;}
export function doorWouldHit(p,open,positions,r=.26){const from=doorPose(p,!open).angle,to=doorPose(p,open).angle;for(let i=1;i<=16;i++){const angle=from+(to-from)*i/16,vertical=p.d>p.w,hx=p.x-(vertical?0:p.w/2),hz=p.z-(vertical?p.d/2:0),lx=vertical?0:p.w/2,lz=vertical?p.d/2:0,b={x:hx+Math.cos(angle)*lx+Math.sin(angle)*lz,z:hz-Math.sin(angle)*lx+Math.cos(angle)*lz,w:p.w,d:p.d,angle};if(positions.some(v=>circleHitsBox(v.x,v.z,v.radius??r,b)))return true;}return false;}
